import Component from 'flarum/common/Component';
import app from 'flarum/forum/app';
export default class GuestWelcomeBox extends Component {
  oninit(vnode) {
    super.oninit(vnode);
  }
  view(vnode) {
    const emptyAvatarImg = app.forum.attribute('imgUrl') || app.forum.attribute('baseUrl') + '/assets/extensions/justoverclock-welcomebox/no-avatar.png';
    return m("div", {
      className: "containerwb"
    }, m("div", {
      className: "backgrwbguest"
    }, m("img", {
      className: "guestavatarimg",
      src: emptyAvatarImg,
      alt: ""
    }), m("div", {
      className: "guesttext"
    }, app.translator.trans('flarum-ext-welcomebox.forum.welcomeguest'))));
  }
}
flarum.reg.add('justoverclock-welcomebox', 'forum/components/GuestWelcomeBox', GuestWelcomeBox);